#!/bin/sh
# The one entry point for contributing to formbook, by a human or an agent.
#
#   sh tools/contribute.sh pick   [--seed N] [--kind K] [--priority P] [--offline]
#   sh tools/contribute.sh claim  <id> [--dry-run] [--fork] [--no-worktree]
#   sh tools/contribute.sh brief  <id>
#   sh tools/contribute.sh verify <id> [--base REF]
#   sh tools/contribute.sh submit <id> [--dry-run] [--skip-verify]
#
# A unit of work is one (court, doc type) pair listed in data/worklist.json (generated by
# tools/worklist.sh). Its id is "<court alias>.<doctype>", e.g. ca1.amicus-brief. The claim is the
# remote branch contrib/<id>. kinds: new-template, new-doctype, add-exemplar, deepen.
#
# Read-only steps (pick, brief, verify) need no push access. claim and submit push; without write
# access they fall back to the fork workflow (a draft PR from your fork is the claim). See CONTRIBUTING.md.
#
# Needs: sh, jq, git. Optional: gh (open PRs, fork), typst + poppler (verify; run tools/bootstrap.sh).
set -eu
ROOT=$(cd "$(dirname "$0")/.." && pwd)
cd "$ROOT"

REMOTE=${CONTRIB_REMOTE:-origin}
BASE=${CONTRIB_BASE:-master}
SLUG_DEFAULT=davidawad/formbook
WL=data/worklist.json

die() {
  echo "contribute.sh: $*" >&2
  exit 1
}
usage() {
  sed -n '2,15p' "$0" | sed 's/^# \{0,1\}//' >&2
  exit 2
}
have() { command -v "$1" > /dev/null 2>&1; }

repo_slug() {
  u=$(git remote get-url "$REMOTE" 2> /dev/null || true)
  s=$(printf '%s' "$u" | sed -n 's#.*github\.com[:/]\([^/]*/[^/]*\)$#\1#p' | sed 's#\.git$##')
  printf '%s' "${s:-$SLUG_DEFAULT}"
}

# ---------------------------------------------------------------- worklist access
# The worklist from origin/master when reachable (so everyone sees the same list), else the local file.
load_worklist() {
  OUT=$1
  if [ "${OFFLINE:-0}" != 1 ] && git fetch -q "$REMOTE" "$BASE" 2> /dev/null &&
    git show "$REMOTE/$BASE:$WL" > "$OUT" 2> /dev/null; then
    return 0
  fi
  [ -f "$WL" ] || die "no $WL here and $REMOTE/$BASE is unreachable; run: sh tools/worklist.sh"
  cp "$WL" "$OUT"
}

unit_json() { # $1 id, $2 worklist file
  jq -c --arg id "$1" '.units[] | select(.id == $id)' "$2" | head -1
}

# The unit's current state from the tree on disk: new | new-template | add-exemplar | deepen | complete
unit_state() { # $1 court_path, $2 doctype
  d="$1/$2"
  [ -d "$d" ] || {
    echo new
    return
  }
  t=0
  for f in "$d"/typst/*.typ; do [ -f "$f" ] && t=1; done
  [ "$t" = 1 ] || {
    echo new-template
    return
  }
  n=0
  for f in "$d"/exemplars/*.pdf; do [ -f "$f" ] && n=$((n + 1)); done
  [ "$n" -gt 0 ] || {
    echo add-exemplar
    return
  }
  min=$(jq -r --arg d "$2" '.doctypes[$d].min_pages // 2' data/doctypes.json)
  pg=$(max_pages "$d")
  if [ "$pg" -gt 0 ] && [ "$pg" -lt "$min" ]; then echo deepen; else echo complete; fi
}

max_pages() {
  best=0
  have pdfinfo || {
    echo 0
    return
  }
  for o in "$1"/samples/OUTPUT-*.pdf; do
    [ -f "$o" ] || continue
    case $o in *.latex.pdf | *.docx.pdf) continue ;; esac
    p=$(pdfinfo "$o" 2> /dev/null | awk '/^Pages:/ {print $2}')
    [ -n "$p" ] && [ "$p" -gt "$best" ] && best=$p
  done
  echo "$best"
}

# ids already taken: remote contrib/* branches, remote court/<alias> branches (whole court claimed),
# and open PR head branches named contrib/* (fork claims). Prints "id <x>" and "court <alias>" lines.
claimed_set() {
  if [ "${OFFLINE:-0}" = 1 ]; then return 0; fi
  git ls-remote --heads "$REMOTE" 'refs/heads/contrib/*' 'refs/heads/court/*' 2> /dev/null |
    sed -n 's#.*refs/heads/contrib/\(.*\)#id \1#p; s#.*refs/heads/court/\(.*\)#court \1#p'
  if have gh; then
    gh pr list --repo "$(repo_slug)" --state open --limit 300 --json headRefName -q '.[].headRefName' 2> /dev/null |
      sed -n 's#^contrib/\(.*\)#id \1#p; s#^court/\(.*\)#court \1#p' || true
  fi
}

is_claimed() { # $1 id $2 alias, claimed list in $CLAIMED_FILE
  grep -qxF "id $1" "$CLAIMED_FILE" || grep -qxF "court $2" "$CLAIMED_FILE"
}

# ---------------------------------------------------------------- pick
cmd_pick() {
  SEED=""
  KIND=""
  PRIO=""
  OFFLINE=0
  while [ $# -gt 0 ]; do
    case $1 in
      --seed)
        SEED=$2
        shift
        ;;
      --kind)
        KIND=$2
        shift
        ;;
      --priority)
        PRIO=$2
        shift
        ;;
      --offline) OFFLINE=1 ;;
      *) usage ;;
    esac
    shift
  done
  case "$KIND" in '' | new-template | new-doctype | add-exemplar | deepen) ;; *) die "--kind must be new-template|new-doctype|add-exemplar|deepen" ;; esac
  case "$PRIO" in '' | high | normal | low) ;; *) die "--priority must be high|normal|low" ;; esac
  if [ -z "$SEED" ]; then
    SEED=$(printf '%s %s %s %s' "$(date +%s)" "$(hostname)" "${RANDOM:-0}" "$$" | cksum | cut -d' ' -f1)
  else
    case $SEED in *[!0-9]*) SEED=$(printf '%s' "$SEED" | cksum | cut -d' ' -f1) ;; esac
  fi

  TMP=$(mktemp -d)
  trap 'rm -rf "$TMP"' EXIT
  load_worklist "$TMP/wl.json"
  CLAIMED_FILE=$TMP/claimed
  claimed_set > "$CLAIMED_FILE" || true

  # candidates: open, not claimed, filtered; sorted by id so the seed maps to the same unit every time
  jq -r --arg k "$KIND" --arg p "$PRIO" '.units[] | select(($k == "" or .kind == $k) and ($p == "" or .priority == $p))
      | [.priority, .id, .alias] | @tsv' "$TMP/wl.json" | sort -k2,2 > "$TMP/all.tsv"
  : > "$TMP/cand.tsv"
  while IFS="$(printf '\t')" read -r pr id al; do
    is_claimed "$id" "$al" && continue
    printf '%s\t%s\n' "$pr" "$id" >> "$TMP/cand.tsv"
  done < "$TMP/all.tsv"

  # without --priority: draw only from the best priority class that still has an unclaimed unit
  if [ -z "$PRIO" ]; then
    for c in high normal low; do
      awk -F'\t' -v c="$c" '$1 == c {print $2}' "$TMP/cand.tsv" > "$TMP/pool"
      [ -s "$TMP/pool" ] && break
    done
  else
    cut -f2 "$TMP/cand.tsv" > "$TMP/pool"
  fi
  N=$(wc -l < "$TMP/pool" | tr -d ' ')
  [ "$N" -gt 0 ] || die "no open unclaimed units match (kind=${KIND:-any} priority=${PRIO:-any})"
  IDX=$((SEED % N + 1))
  ID=$(sed -n "${IDX}p" "$TMP/pool")

  unit_json "$ID" "$TMP/wl.json" | jq -r '"id:       \(.id)\nkind:     \(.kind)\npriority: \(.priority)\ncourt:    \(.alias)  \(.court_path)\ndoctype:  \(.doctype)  (\(.title))\nfolder:   \(.folder)\nnote:     \(.note)"'
  echo "seed:     $SEED   (pool of $N unclaimed; reproduce: sh tools/contribute.sh pick --seed $SEED${KIND:+ --kind $KIND}${PRIO:+ --priority $PRIO})"
  echo "next:     sh tools/contribute.sh claim $ID   &&   sh tools/contribute.sh brief $ID"
}

# ---------------------------------------------------------------- claim
cmd_claim() {
  ID=""
  DRY=0
  FORK=0
  WT=1
  OFFLINE=0
  while [ $# -gt 0 ]; do
    case $1 in
      --dry-run) DRY=1 ;;
      --fork) FORK=1 ;;
      --no-worktree) WT=0 ;;
      --offline) OFFLINE=1 ;;
      -*) usage ;;
      *) ID=$1 ;;
    esac
    shift
  done
  [ -n "$ID" ] || usage
  TMP=$(mktemp -d)
  trap 'rm -rf "$TMP"' EXIT
  load_worklist "$TMP/wl.json"
  U=$(unit_json "$ID" "$TMP/wl.json")
  [ -n "$U" ] || die "no such unit: $ID (not in $WL)"
  AL=$(printf '%s' "$U" | jq -r .alias)
  CP=$(printf '%s' "$U" | jq -r .court_path)
  DT=$(printf '%s' "$U" | jq -r .doctype)

  git fetch -q "$REMOTE" "$BASE" 2> /dev/null || true
  [ "$(unit_state "$CP" "$DT")" != complete ] || die "$ID is already complete in this checkout; git pull and run: sh tools/contribute.sh pick"
  CLAIMED_FILE=$TMP/claimed
  claimed_set > "$CLAIMED_FILE" || true
  if is_claimed "$ID" "$AL"; then
    die "$ID is already claimed (a contrib/$ID or court/$AL branch, or an open PR, exists). Run: sh tools/contribute.sh pick"
  fi
  BR=contrib/$ID
  SHA=$(git rev-parse "$REMOTE/$BASE")

  if [ "$DRY" = 1 ]; then
    echo "dry run: $ID is open and unclaimed."
    echo "would run: git push --force-with-lease=refs/heads/$BR: $REMOTE $SHA:refs/heads/$BR   (atomic: fails if $BR exists)"
    echo "would run: git worktree add .worktrees/$ID -b $BR $SHA"
    echo "no write access: would use the fork workflow instead (gh repo fork; draft PR $BR = the claim)"
    return 0
  fi

  if [ "$FORK" = 0 ] && git push -q --force-with-lease="refs/heads/$BR:" "$REMOTE" "$SHA:refs/heads/$BR" 2> "$TMP/push.err"; then
    echo "claimed: $ID  (remote branch $BR created from $REMOTE/$BASE)"
    if [ "$WT" = 1 ]; then
      git fetch -q "$REMOTE" "$BR"
      git worktree add -q ".worktrees/$ID" -B "$BR" "$REMOTE/$BR" 2> /dev/null && git -C ".worktrees/$ID" branch -q --set-upstream-to="$REMOTE/$BR" 2> /dev/null || true
      echo "worktree: $ROOT/.worktrees/$ID   (work only there)"
    fi
    echo "next: sh tools/contribute.sh brief $ID"
    return 0
  fi
  if [ "$FORK" = 0 ] && grep -qi 'already exists\|stale info\|rejected' "$TMP/push.err" 2> /dev/null; then
    die "lost the race: $BR was created by someone else first. Run: sh tools/contribute.sh pick"
  fi

  # no write access: fork workflow. The claim is a draft PR whose head branch is contrib/<id>.
  have gh || die "no push access to $REMOTE and gh is not installed. Fork the repo on GitHub, add your fork as a remote, push $BR there, and open a draft PR titled 'claim($ID)'."
  LOGIN=$(gh api user -q .login) || die "gh is not logged in (gh auth login)"
  gh repo fork "$(repo_slug)" --clone=false > /dev/null 2>&1 || true
  FURL=$(gh repo view "$LOGIN/$(repo_slug | cut -d/ -f2)" --json url -q .url).git
  git remote get-url fork > /dev/null 2>&1 || git remote add fork "$FURL"
  git fetch -q fork 2> /dev/null || true
  git worktree add -q ".worktrees/$ID" -B "$BR" "$SHA"
  git -C ".worktrees/$ID" commit -q --allow-empty -m "claim($ID): start $(printf '%s' "$U" | jq -r .kind)"
  git -C ".worktrees/$ID" push -q -u fork "$BR"
  gh pr create --repo "$(repo_slug)" --base "$BASE" --head "$LOGIN:$BR" --draft \
    --title "claim($ID): $(printf '%s' "$U" | jq -r .kind)" \
    --body "Claim of work unit \`$ID\` (see CONTRIBUTING.md). Draft until the work is verified; \`sh tools/contribute.sh submit $ID\` marks it ready." > /dev/null
  echo "claimed via fork: $ID  (draft PR from $LOGIN:$BR)"
  echo "worktree: $ROOT/.worktrees/$ID"
  echo "next: sh tools/contribute.sh brief $ID"
}

# ---------------------------------------------------------------- brief
cmd_brief() {
  ID=${1:-}
  [ -n "$ID" ] || usage
  TMP=$(mktemp -d)
  trap 'rm -rf "$TMP"' EXIT
  OFFLINE=1
  load_worklist "$TMP/wl.json"
  U=$(unit_json "$ID" "$TMP/wl.json")
  [ -n "$U" ] || die "no such unit: $ID"
  KIND=$(printf '%s' "$U" | jq -r .kind)
  AL=$(printf '%s' "$U" | jq -r .alias)
  CP=$(printf '%s' "$U" | jq -r .court_path)
  DT=$(printf '%s' "$U" | jq -r .doctype)
  FOLDER=$CP/$DT
  TITLE=$(printf '%s' "$U" | jq -r .title)
  LEVEL=$(printf '%s' "$U" | jq -r .level)
  WHAT=$(jq -r --arg d "$DT" '.doctypes[$d].what // ""' data/doctypes.json)
  MIN=$(jq -r --arg d "$DT" '.doctypes[$d].min_pages // 2' data/doctypes.json)
  SIB=$(for s in "$CP"/*/; do [ -d "$s/typst" ] && [ -d "$s/exemplars" ] && printf '%s ' "${s%/}"; done 2> /dev/null || true)

  cat << EOF
TASK $ID  [$KIND]
$TITLE for $(jq -r --arg a "$AL" '.courts[$a].name' data/index.json) ($AL, level: $LEVEL)
Folder (your whole change lives here and nowhere else): $FOLDER/
Doc type means: $WHAT

READ FIRST
  AGENTS.md and docs/EVAL-LOOP.md (quality tiers, banned practices). Reference doc-type folder to copy the
  structure of: courts/first-circuit/court-of-appeals/opening-brief/  (README.md, typst/, exemplars/, samples/).
EOF
  [ -n "$SIB" ] && printf '  Sibling doc types in this court you can reuse patterns from: %s\n' "$SIB"
  [ -f "$CP/rules.md" ] && echo "  The court's rules, already researched: $CP/rules.md"
  [ -f "$CP/README.md" ] && echo "  Court notes: $CP/README.md"

  case $KIND in
    new-template | new-doctype)
      cat << EOF

DO (kind $KIND)
  1. Research the governing rules for a $DT in $AL from primary sources (court rules, local rules, clerk's
     form requirements). Note rule number, URL and date verified. These decide the layout (tier 1).
  2. Find 1 to 3 real, public filings of this type in this court (CourtListener RECAP, the court's own
     site, state e-filing archives). Save the PDFs as $FOLDER/exemplars/FILED-EXAMPLE-<case-slug>-<doctype>.pdf.
     Public court records only: no sealed, redacted-by-mistake or private documents.
  3. Write $FOLDER/exemplars/SOURCE.md: for every PDF the file name, filer, case, docket number, date
     filed, the exact URL you downloaded it from, date retrieved. See the first-circuit example.
  4. Write the typst template: $FOLDER/typst/main.typ (entry point; reads the sample via
     --input sample=...) plus $FOLDER/typst/<court>-$DT.typ. Rule-driven and content-agnostic: no
     case-specific text, no coordinates measured off the exemplar. Fonts only from fonts/.
  5. Write $FOLDER/samples/INPUT-<slug>.md (markdown with YAML frontmatter) transcribed from the exemplar,
     and, if you can, a second structurally different fictional INPUT.
  6. Render: sh tools/render.sh $FOLDER samples/INPUT-<slug>.md      (any typst warning fails)
     then: sh tools/overlay.sh $FOLDER <slug>   -> samples/OUTPUT-<slug>.pdf, OVERLAY-<slug>.pdf/.txt
  7. Look at EVERY page of the overlay against the exemplar. Fix tier-1 and tier-2 defects; do not chase tier 3.
  8. Write $FOLDER/README.md: rules table (rule, requirement, where the template uses it), file table,
     frontmatter contract, known gaps. Mark BLOCKED items honestly.
EOF
      ;;
    add-exemplar)
      cat << EOF

DO (kind add-exemplar): the template exists but has no filed exemplar to be judged against.
  1. Find 1 to 3 real, public filings of this doc type in this court by different filers.
  2. Save as $FOLDER/exemplars/FILED-EXAMPLE-<case-slug>-<doctype>.pdf and record each in
     $FOLDER/exemplars/SOURCE.md (file, filer, case, docket no., date filed, exact URL, date retrieved).
  3. Transcribe one exemplar into $FOLDER/samples/INPUT-<slug>.md; render it:
     sh tools/render.sh $FOLDER samples/INPUT-<slug>.md ; sh tools/overlay.sh $FOLDER <slug>
  4. Review every overlay page; fix tier-1 and tier-2 defects in $FOLDER/typst/ only.
  5. Update $FOLDER/README.md (remove the BLOCKED: no exemplar line, add the exemplar and findings).
EOF
      ;;
    deepen)
      cat << EOF

DO (kind deepen): the sample is shorter than a realistic $DT (about $MIN+ pages), so layout under real load
is untested (page breaks, long tables, many footnotes, long headings, certificates).
  1. Read $FOLDER/README.md "Known gaps" and the existing samples.
  2. Extend or add a samples/INPUT-*.md so the rendered output reaches at least $MIN pages and exercises
     every section the court requires (tables, footnotes, block quotes, certificates, signature block).
  3. Re-render and re-overlay; fix tier-1 and tier-2 defects in typst/ (content-agnostic fixes only).
  4. Update README.md known gaps.
EOF
      ;;
  esac

  cat << EOF

QUALITY BAR (summary; the full text is docs/EVAL-LOOP.md)
  tier 1 mandated form (font, size, margins, spacing, length limits, required sections, certificates): perfect.
  tier 2 professional convention (cover, TOC/TOA, headings, caption, signature block): looks professional,
         judged against exemplars from different filers. tier 3 one filer's style: do not chase.
  Banned: case-specific text in typst/, forced line breaks tuned to one document, coordinates measured off a
  filed PDF, system fonts, aggregate scores, claiming a page was reviewed that you did not look at, new Python.
  Never set "status": "done" in any court.json. Do not touch files outside $FOLDER/.

VERIFY (must pass before you submit)
  sh tools/contribute.sh verify $ID
  Needs typst and poppler on PATH: sh tools/bootstrap.sh, then export PATH="\$HOME/.local/share/formbook/env/bin:\$PATH"

SUBMIT
  sh tools/contribute.sh submit $ID        (commits, pushes contrib/$ID, opens the PR; falls back to a compare URL)
  If you cannot finish, release the claim: delete the remote branch contrib/$ID (git push $REMOTE --delete contrib/$ID)
  or close your draft PR, and say what blocked you in the PR or branch description.
EOF
}

# ---------------------------------------------------------------- verify
PASSN=0
FAILN=0
ok() {
  PASSN=$((PASSN + 1))
  printf 'PASS  %s\n' "$*"
}
bad() {
  FAILN=$((FAILN + 1))
  printf 'FAIL  %s\n' "$*"
}

cmd_verify() {
  ID=""
  VBASE=""
  while [ $# -gt 0 ]; do
    case $1 in
      --base)
        VBASE=$2
        shift
        ;;
      -*) usage ;;
      *) ID=$1 ;;
    esac
    shift
  done
  [ -n "$ID" ] || usage
  TMP=$(mktemp -d)
  trap 'rm -rf "$TMP"' EXIT
  OFFLINE=1
  load_worklist "$TMP/wl.json"
  U=$(unit_json "$ID" "$TMP/wl.json")
  if [ -z "$U" ]; then
    # a finished unit leaves the worklist; fall back to parsing "<alias>.<doctype>" against the index
    AL=${ID%%.*}
    DT=${ID#*.}
    CP=$(jq -r --arg a "$AL" '.courts[$a].path // empty' data/index.json)
    [ -n "$CP" ] || die "unknown unit or court alias: $ID"
  else
    AL=$(printf '%s' "$U" | jq -r .alias)
    CP=$(printf '%s' "$U" | jq -r .court_path)
    DT=$(printf '%s' "$U" | jq -r .doctype)
  fi
  F=$CP/$DT
  MIN=$(jq -r --arg d "$DT" '.doctypes[$d].min_pages // 2' data/doctypes.json)
  echo "verify $ID  ($F/)"

  # 1. layout
  [ -d "$F" ] || {
    bad "layout: folder $F/ does not exist"
    echo "RESULT: FAIL ($FAILN failed)"
    exit 1
  }
  [ -s "$F/README.md" ] && ok "layout: README.md" || bad "layout: README.md missing or empty"
  [ -s "$F/typst/main.typ" ] && ok "layout: typst/main.typ" || bad "layout: typst/main.typ missing"
  nt=0
  for f in "$F"/typst/*.typ; do [ -f "$f" ] && nt=$((nt + 1)); done
  [ "$nt" -ge 2 ] && ok "layout: typst template file(s) beside main.typ" || bad "layout: expected typst/main.typ plus a template file (found $nt .typ files)"
  ne=0
  for f in "$F"/exemplars/*.pdf; do [ -f "$f" ] && ne=$((ne + 1)); done
  [ "$ne" -ge 1 ] && ok "layout: $ne exemplar pdf(s)" || bad "layout: no exemplars/*.pdf (a template without a filed exemplar is BLOCKED, not done)"
  if [ -s "$F/exemplars/SOURCE.md" ]; then
    ok "layout: exemplars/SOURCE.md"
    for f in "$F"/exemplars/*.pdf; do
      [ -f "$f" ] || continue
      b=$(basename "$f")
      grep -qF "$b" "$F/exemplars/SOURCE.md" || bad "source: $b is not described in exemplars/SOURCE.md"
    done
    grep -q 'https\?://' "$F/exemplars/SOURCE.md" && ok "source: SOURCE.md records a URL" || bad "source: SOURCE.md has no http(s) URL for the exemplar"
  else
    [ "$ne" -ge 1 ] && bad "layout: exemplars/SOURCE.md missing (every exemplar needs its public source URL)"
  fi
  ni=0
  for f in "$F"/samples/INPUT-*.md; do [ -f "$f" ] && ni=$((ni + 1)); done
  [ "$ni" -ge 1 ] && ok "layout: $ni samples/INPUT-*.md" || bad "layout: no samples/INPUT-*.md"

  # 2. render each INPUT; OUTPUT committed; OVERLAY when an exemplar exists
  if have typst; then
    for f in "$F"/samples/INPUT-*.md; do
      [ -f "$f" ] || continue
      sid=$(basename "$f" .md)
      sid=${sid#INPUT-}
      if sh tools/render.sh "$F" "samples/INPUT-$sid.md" "$TMP/out-$sid.pdf" > "$TMP/render.log" 2>&1; then
        ok "render: INPUT-$sid.md compiles with no typst warnings"
      else
        bad "render: INPUT-$sid.md failed: $(tail -3 "$TMP/render.log" | tr '\n' ' ')"
      fi
      [ -s "$F/samples/OUTPUT-$sid.pdf" ] && ok "layout: OUTPUT-$sid.pdf committed" || bad "layout: samples/OUTPUT-$sid.pdf missing for INPUT-$sid.md"
    done
  else
    bad "render: typst not on PATH (run tools/bootstrap.sh and add its bin/ to PATH)"
  fi
  if [ "$ne" -ge 1 ]; then
    nv=0
    for f in "$F"/samples/OVERLAY-*.pdf; do [ -f "$f" ] && nv=$((nv + 1)); done
    [ "$nv" -ge 1 ] && ok "overlay: $nv OVERLAY pdf(s) present" || bad "overlay: exemplar exists but no samples/OVERLAY-*.pdf (run tools/overlay.sh)"
  fi

  # 3. deepen: page count
  pg=$(max_pages "$F")
  if have pdfinfo; then
    [ "$pg" -ge "$MIN" ] && ok "depth: longest OUTPUT is $pg pages (>= $MIN)" || bad "depth: longest OUTPUT is $pg pages; a realistic $DT is $MIN+ (kind deepen)"
  fi

  # 4. no case-specific text in typst/
  probes=$TMP/probes
  : > "$probes"
  for f in "$F"/samples/INPUT-*.md; do
    [ -f "$f" ] || continue
    # frontmatter string values that identify a case: contain a digit, or are an ALL-CAPS party name
    awk 'NR == 1 && $0 == "---" {fm = 1; next} fm && $0 == "---" {exit} fm {print}' "$f" |
      sed -n 's/^[^:]*:[[:space:]]*"\(.*\)"[[:space:]]*,\{0,1\}$/\1/p; s/^[[:space:]]*-[[:space:]]*"\(.*\)"[[:space:]]*$/\1/p' |
      awk 'length($0) >= 8 && (/[0-9]/ || /^[A-Z][A-Z .,&-]*[A-Z]\.?,?$/)' >> "$probes" || true
    # body: any 8-word run of the sample's prose
    awk 'BEGIN{fm=0} NR==1 && $0=="---"{fm=1; next} fm && $0=="---"{fm=0; next} !fm && NF>=10 {print $1" "$2" "$3" "$4" "$5" "$6" "$7" "$8}' "$f" >> "$probes"
  done
  sort -u "$probes" | grep -v '^$' > "$TMP/probes.u" || true
  hits=""
  if [ -s "$TMP/probes.u" ]; then
    hits=$(cat "$F"/typst/*.typ 2> /dev/null | grep -F -f "$TMP/probes.u" | head -3 || true)
  fi
  dockets=$(cat "$F"/typst/*.typ 2> /dev/null | grep -En '[0-9]{1,2}:[0-9]{2}-(cv|cr|bk|ap|mc)-[0-9]+|No\. [0-9]{2}-[0-9]{3,}' | head -3 || true)
  if [ -z "$hits" ] && [ -z "$dockets" ]; then
    ok "content: no case-specific text found in typst/"
  else
    [ -n "$hits" ] && bad "content: typst/ contains text copied from a sample: $(printf '%s' "$hits" | head -1 | cut -c1-120)"
    [ -n "$dockets" ] && bad "content: typst/ contains a docket number: $(printf '%s' "$dockets" | head -1 | cut -c1-120)"
  fi

  # 5. scope: nothing changed outside the unit's folder
  if git rev-parse -q --verify "$REMOTE/$BASE" > /dev/null; then B=$REMOTE/$BASE; elif git rev-parse -q --verify "$BASE" > /dev/null; then B=$BASE; else B=""; fi
  [ -n "$VBASE" ] && B=$VBASE
  if [ -n "$B" ]; then
    {
      git diff --name-only "$B"...HEAD 2> /dev/null || true
      git diff --name-only HEAD 2> /dev/null || true
      git ls-files --others --exclude-standard 2> /dev/null || true
    } | sort -u | grep -v '^$' > "$TMP/changed" || true
    stray=$(grep -v "^$F/" "$TMP/changed" | head -5 || true)
    if [ -z "$stray" ]; then
      ok "scope: only $F/ changed vs $B ($(wc -l < "$TMP/changed" | tr -d ' ') files)"
    else
      bad "scope: files outside $F/ changed: $(printf '%s' "$stray" | tr '\n' ' ')"
    fi
    if grep -q 'court\.json$' "$TMP/changed" 2> /dev/null; then
      bad "scope: a court.json changed (status done is set by the maintainer only)"
    fi
  else
    bad "scope: cannot find $REMOTE/$BASE or $BASE to diff against (pass --base REF)"
  fi

  if [ "$FAILN" -eq 0 ]; then
    echo "RESULT: PASS ($PASSN checks)"
  else
    echo "RESULT: FAIL ($FAILN failed, $PASSN passed)"
    exit 1
  fi
}

# ---------------------------------------------------------------- submit
cmd_submit() {
  ID=""
  DRY=0
  SKIPV=0
  OFFLINE=0
  while [ $# -gt 0 ]; do
    case $1 in
      --dry-run) DRY=1 ;;
      --skip-verify) SKIPV=1 ;;
      --offline) OFFLINE=1 ;;
      -*) usage ;;
      *) ID=$1 ;;
    esac
    shift
  done
  [ -n "$ID" ] || usage
  TMP=$(mktemp -d)
  trap 'rm -rf "$TMP"' EXIT
  AL=${ID%%.*}
  DT=${ID#*.}
  CP=$(jq -r --arg a "$AL" '.courts[$a].path // empty' data/index.json)
  [ -n "$CP" ] || die "unknown court alias in $ID"
  F=$CP/$DT
  BR=contrib/$ID
  SLUG=$(repo_slug)
  KIND=$(jq -r --arg id "$ID" '(.units[] | select(.id == $id) | .kind) // "work"' "$WL")

  if [ "$SKIPV" = 0 ]; then
    sh "$0" verify "$ID" > "$TMP/verify.txt" 2>&1 || {
      cat "$TMP/verify.txt"
      die "verify failed; fix and rerun (or --skip-verify, which maintainers will see in the PR)"
    }
  else
    echo "verify skipped by --skip-verify" > "$TMP/verify.txt"
  fi
  {
    echo "Work unit: \`$ID\` ($KIND), folder \`$F/\`."
    echo
    echo "## Verification"
    echo '```'
    cat "$TMP/verify.txt"
    echo '```'
    echo
    echo "## Exemplars (public court records)"
    if [ -s "$F/exemplars/SOURCE.md" ]; then grep -E 'URL|Filer|Case|Docket' "$F/exemplars/SOURCE.md" | head -12; else echo "none recorded"; fi
    echo
    echo "## Tier-2 findings left open / BLOCKED items"
    echo "(list by page, from the overlay review; or write: none)"
    echo
    echo "## Disclosure"
    echo "Prepared with AI assistance (agent: <name and model>). I reviewed every overlay page. Exemplars are public court records; no sealed or private documents."
  } > "$TMP/body.md"
  TITLE="feat($AL/$DT): $KIND"

  if [ "$DRY" = 1 ]; then
    echo "dry run: would run: git add $F && git commit -m '$TITLE' (if dirty)"
    echo "dry run: would run: git push -u $REMOTE HEAD:refs/heads/$BR  (fork remote if no write access)"
    echo "dry run: would run: gh pr create --repo $SLUG --base $BASE --head $BR --title '$TITLE' --body-file <body>   (or gh pr ready + edit if a draft claim PR exists)"
    echo "compare URL: https://github.com/$SLUG/compare/$BASE...$BR?expand=1"
    echo "---- PR body ----"
    cat "$TMP/body.md"
    return 0
  fi

  git add -- "$F"
  if ! git diff --cached --quiet; then
    git commit -q -m "$TITLE"
  fi
  PUSHR=$REMOTE
  git push -q -u "$REMOTE" "HEAD:refs/heads/$BR" 2> "$TMP/push.err" || {
    if git remote get-url fork > /dev/null 2>&1 && git push -q -u fork "HEAD:refs/heads/$BR" 2> "$TMP/push.err"; then
      PUSHR=fork
    else
      cat "$TMP/push.err" >&2
      die "push failed (no write access? run: sh tools/contribute.sh claim $ID --fork first)"
    fi
  }
  HEAD_REF=$BR
  [ "$PUSHR" = fork ] && HEAD_REF="$(gh api user -q .login):$BR"
  if have gh; then
    existing=$(gh pr list --repo "$SLUG" --state open --head "$BR" --json number -q '.[0].number' 2> /dev/null || true)
    if [ -n "$existing" ]; then
      gh pr edit "$existing" --repo "$SLUG" --title "$TITLE" --body-file "$TMP/body.md" > /dev/null
      gh pr ready "$existing" --repo "$SLUG" 2> /dev/null || true
      echo "updated and marked ready: PR #$existing"
    else
      gh pr create --repo "$SLUG" --base "$BASE" --head "$HEAD_REF" --title "$TITLE" --body-file "$TMP/body.md"
    fi
  else
    echo "gh not installed. Open: https://github.com/$SLUG/compare/$BASE...$HEAD_REF?expand=1"
    echo "title: $TITLE"
    echo "---- paste as the PR body ----"
    cat "$TMP/body.md"
  fi
}

# ---------------------------------------------------------------- dispatch
[ $# -ge 1 ] || usage
sub=$1
shift
case $sub in
  pick) cmd_pick "$@" ;;
  claim) cmd_claim "$@" ;;
  brief) cmd_brief "$@" ;;
  verify) cmd_verify "$@" ;;
  submit) cmd_submit "$@" ;;
  -h | --help | help) usage ;;
  *) usage ;;
esac
